<?php
require_once __DIR__ . '/../includes/auth.php'; require __DIR__ . '/../includes/db.php';
$msg=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $car_id=(int)($_POST['car_id']??0); $date=$_POST['log_date']??date('Y-m-d'); $mileage=(int)($_POST['mileage']??0)?:null; $liters=money_value($_POST['liters']??0); $cost=money_value($_POST['cost']??0); $station=trim($_POST['fuel_station']??''); $notes=trim($_POST['notes']??''); $user=$_SESSION['user_id']??null;
    if(!$car_id||!$date) $error='Car and date are required.'; else { $stmt=$conn->prepare("INSERT INTO fuel_logs (car_id,log_date,mileage,liters,cost,fuel_station,notes,created_by) VALUES (?,?,?,?,?,?,?,?)"); $stmt->bind_param('isiddssi',$car_id,$date,$mileage,$liters,$cost,$station,$notes,$user); if($stmt->execute()){ if($mileage) $conn->query("UPDATE cars SET current_mileage=GREATEST(IFNULL(current_mileage,0),".(int)$mileage.") WHERE id=$car_id"); $msg='Fuel log saved.';} else $error='Could not save fuel log.'; }
}
$cars=$conn->query("SELECT cars.id,cars.reg_no,makes.name AS make_name,models.name AS model_name,car_years.year AS car_year FROM cars JOIN makes ON cars.make_id=makes.id JOIN models ON cars.model_id=models.id JOIN car_years ON cars.year_id=car_years.id ORDER BY makes.name,models.name");
$list=$conn->query("SELECT f.*, ca.reg_no, m.name AS make_name, mo.name AS model_name, y.year AS car_year FROM fuel_logs f JOIN cars ca ON f.car_id=ca.id LEFT JOIN makes m ON ca.make_id=m.id LEFT JOIN models mo ON ca.model_id=mo.id LEFT JOIN car_years y ON ca.year_id=y.id ORDER BY f.log_date DESC,f.id DESC");
?>
<!DOCTYPE html><html><head><title>Fuel & Mileage Tracking</title></head><body><?php include __DIR__.'/../includes/header.php'; include __DIR__.'/../includes/leftsidebar.php';?><div class="content-page"><h2>Fuel & Mileage Tracking</h2><?php if($msg):?><p class="success-msg"><?=h($msg)?></p><?php endif;?><?php if($error):?><p class="error-msg"><?=h($error)?></p><?php endif;?><div class="card-box"><form method="POST" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;align-items:end"><div><label>Car</label><select name="car_id" required><option value="">Select</option><?php while($c=$cars->fetch_assoc()):?><option value="<?=h($c['id'])?>"><?=h(car_display_name($c))?></option><?php endwhile;?></select></div><div><label>Date</label><input type="date" name="log_date" value="<?=date('Y-m-d')?>" required></div><div><label>Mileage</label><input type="number" name="mileage"></div><div><label>Liters</label><input type="number" step="0.01" name="liters"></div><div><label>Cost</label><input type="number" step="0.01" name="cost"></div><div><label>Fuel Station</label><input name="fuel_station"></div><div style="grid-column:1/-1"><label>Notes</label><textarea name="notes"></textarea></div><button>Save Fuel Log</button></form></div><div class="table-responsive"><table class="table" border="1" cellpadding="10"><tr><th>Date</th><th>Car</th><th>Mileage</th><th>Liters</th><th>Cost</th><th>Station</th><th>Notes</th></tr><?php if($list&&$list->num_rows): while($r=$list->fetch_assoc()):?><tr><td><?= h(cr_date($r['log_date'])) ?></td><td><?=h(car_display_name($r))?></td><td><?=h($r['mileage'])?></td><td><?=number_format((float)$r['liters'],2)?></td><td><?=money((float)$r['cost'])?></td><td><?=h($r['fuel_station'])?></td><td><?=h($r['notes'])?></td></tr><?php endwhile;else:?><tr><td colspan="7">No fuel logs yet.</td></tr><?php endif;?></table></div></div></body></html>
